python3 -c "
import csv
from collections import defaultdict, Counter

rows = []
with open('benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# Long question sub-parts analysis
print('=== LONG QUESTION SUB-PARTS PER YEAR ===')
years = [2015,2016,2017,2018,2019,2021,2022,2023,2024,2025]
for y in years:
    long_qs = [r for r in rows if int(r['year'])==y and r['type']=='Long']
    total_parts = 0
    for q in long_qs:
        parts = len(q['question'].split('\$'))
        total_parts += parts
    print(f'{y}: {len(long_qs)} long questions, {total_parts} sub-parts')

# Unique topic patterns across Long questions
print('\n=== LONG QUESTION TOPIC PATTERNS ===')
long_topics = defaultdict(list)
for r in rows:
    if r['type'] == 'Long':
        y = int(r['year'])
        q = r['question'].lower()
        topics = []
        if 'loop' in q or 'for ' in q or 'while' in q: topics.append('Loops')
        if 'function' in q or 'recursion' in q or 'recursive' in q: topics.append('Functions')
        if 'database' in q or 'dbms' in q or 'rdbms' in q: topics.append('Database')
        if 'ms-access' in q or 'ms access' in q: topics.append('MS-Access')
        if 'data type' in q or 'data types' in q: topics.append('Data Types')
        if 'operator' in q: topics.append('Operators')
        if 'control' in q or 'if-else' in q or 'switch' in q or 'selection' in q or 'decision' in q: topics.append('Control Structures')
        if 'i/o' in q or 'input/output' in q or 'format specif' in q: topics.append('I/O Functions')
        if 'file' in q: topics.append('File Handling')
        if 'model' in q or 'hierarchical' in q or 'network' in q or 'relational' in q: topics.append('DB Models')
        if 'array' in q: topics.append('Arrays')
        if 'object' in q: topics.append('DB Objects')
        if 'normalization' in q: topics.append('Normalization')
        if 'struct' in q and 'control' not in q: topics.append('Structures (C)')
        if 'er diagram' in q or 'schema' in q: topics.append('ER/Schema')
        if 'storage class' in q: topics.append('Storage Classes')
        print(f'{y}: {\" | \".join(topics) if topics else \"Other\"} -- {q[:80]}')

# Repeated question patterns (similar questions across years)
print('\n=== QUESTION BLOOM TAXONOMY ===')
for t in ['MCQs', 'Short', 'Long']:
    qs = [r for r in rows if r['type'] == t]
    action_words = Counter()
    for q in qs:
        text = q['question'].lower()
        if text.startswith('what '): action_words['what'] += 1
        elif text.startswith('define '): action_words['define'] += 1
        elif text.startswith('explain '): action_words['explain'] += 1
        elif text.startswith('write '): action_words['write'] += 1
        elif text.startswith('differentiate '): action_words['differentiate'] += 1
        elif 'difference between' in text: action_words['difference'] += 1
        elif text.startswith('how '): action_words['how'] += 1
    print(f'{t}: {dict(action_words)}')

# Three structural eras
print('\n=== STRUCTURAL ERAS ===')
print('Era 1 (2015-2016): 27 questions/year (15 MCQ + 9 Short + 3 Long)')
print('Era 2 (2017-2019): 36 questions/year (15 MCQ + 18 Short + 3 Long)')
print('Era 3 (2021-2025): 33 questions/year (15 MCQ + 15 Short + 3 Long)')
print('Note: 2020 absent (likely COVID-19 cancellation)')
"

